plan_test = '''#!/usr/bin/env bats
# Acceptance tests for benchmark runner --plan mode (fizeau-2eeb9a43 AC1-2)

SCRIPT_DIR="$(cd "$(dirname "$BATS_TEST_FILENAME")" && cd .. && pwd)"
BENCHMARK_SCRIPT="${SCRIPT_DIR}/benchmark"

setup() {
  export BENCH_TASKS_DIR_DEFAULT="${SCRIPT_DIR}/external/terminal-bench-2"
  export BENCH_HARBOR_DIGEST_OVERRIDE="test-digest-sha"
}

# AC1: --plan creates NO files, builds NO Docker images
@test "Test_PlanIsPure" {
  output=$("${BENCHMARK_SCRIPT}" --plan --profile sindri-lucebox --bench-set tb-2-1-canary 2>&1)
  [[ -n "${output}" ]]
  echo "${output}" | head -1 | grep -q "profile="
}

# AC1: --plan prints the matrix
@test "Test_PlanPrintsMatrix" {
  output=$("${BENCHMARK_SCRIPT}" --plan --profile sindri-lucebox --bench-set tb-2-1-canary 2>&1)
  line_count=$(echo "${output}" | wc -l)
  [[ ${line_count} -eq 9 ]]
}

# AC2: Listing subcommands work
@test "Test_ListingSubcommands_profiles" {
  output=$("${BENCHMARK_SCRIPT}" profiles)
  [[ -n "${output}" ]]
  echo "${output}" | grep -q "sindri-lucebox"
}

@test "Test_ListingSubcommands_bench_sets" {
  output=$("${BENCHMARK_SCRIPT}" bench-sets)
  [[ -n "${output}" ]]
  echo "${output}" | grep -q "tb-2-1-canary"
}

# AC3: validate exits 0 on valid config
@test "Test_Validate" {
  "${BENCHMARK_SCRIPT}" validate
}
'''

# Create matrix.bats test file
matrix_test = '''#!/usr/bin/env bats
# Acceptance tests for matrix expansion (fizeau-2eeb9a43 AC4)

SCRIPT_DIR="$(cd "$(dirname "$BATS_TEST_FILENAME")" && cd .. && pwd)"
BENCHMARK_SCRIPT="${SCRIPT_DIR}/benchmark"
TEST_OUT_DIR=""

setup() {
  TEST_OUT_DIR="$(mktemp -d)"
  export BENCH_TASKS_DIR_DEFAULT="${SCRIPT_DIR}/external/terminal-bench-2"
}

teardown() {
  [[ -d "${TEST_OUT_DIR}" ]] && rm -rf "${TEST_OUT_DIR}"
}

# AC4: Matrix expansion with inline tasks
@test "Test_MatrixExpansion_inline_tasks" {
  local test_benches="${TEST_OUT_DIR}/benches"
  mkdir -p "${test_benches}"

  cat > "${test_benches}/inline.yaml" <<'EOF'
id: inline
framework: terminal-bench
dataset: tb-2-1
default_reps: 2
tasks:
  - task1
  - task2
EOF

  output=$(BENCH_SETS_DIR="${test_benches}" \\
    "${BENCHMARK_SCRIPT}" --plan --profile sindri-lucebox --bench-set inline 2>&1)

  line_count=$(echo "${output}" | wc -l)
  [[ ${line_count} -eq 4 ]]
  echo "${output}" | grep -q "task=task1"
  echo "${output}" | grep -q "task=task2"
}

# AC4: Default task executor for terminal-bench is harbor
@test "Test_MatrixExpansion_default_executor_harbor" {
  output=$("${BENCHMARK_SCRIPT}" --plan --profile sindri-lucebox --bench-set tb-2-1-canary 2>&1)
  echo "${output}" | grep -q "task_executor=harbor"
}
'''

# Write the files
with open("scripts/benchmark/tests/plan.bats", "w") as f:
    f.write(plan_test)

with open("scripts/benchmark/tests/matrix.bats", "w") as f:
    f.write(matrix_test)

import os
os.chmod("scripts/benchmark/tests/plan.bats", 0o755)
os.chmod("scripts/benchmark/tests/matrix.bats", 0o755)

print("Test files created successfully")
PYTHON_EOF

